459	\begin{theorem}[EPR projection estimates]\label{thm:qld-epr-projection-estimates}
460		\lean{MIPStarRE.QPBT.Extraction.pauliCorrelation_mul_eq_epr}
461		\lean{MIPStarRE.QPBT.Extraction.norm_sub_eprProjection_le}
462		\lean{MIPStarRE.QPBT.ProjectiveSetting.idealExpState_extractionAux0}
463		\lean{MIPStarRE.QPBT.ProjectiveSetting.exists_unit_aux_near_eprProjection}
464		\leanok
465		\uses{def:generalized-pauli, def:EPR, lem:projective-strategy-setup}
466		This auxiliary statement isolates the projection and normalization
467		calculations in the proof of Lemma~\ref{lem:qld-unitary}.
468		Write $E=\ket{\mathrm{EPR}_q}^{\ot M}$ and
469		\[
470			H_W=\frac{1}{q^M}\sum_{u\in\F_q^M}\tau^W(u)\ot\tau^W(u).
471		\]
472		Then $H_XH_Z=\ket{E}\bra{E}$. Let $R$ be an auxiliary register and
473		$\vartheta$ a unit vector on $R\ot A''\ot B''$. If $\delta\geq0$ and
474		\[
475			\Re\langle\vartheta,(\Id_R\ot H_W)\vartheta\rangle
476			\geq1-\delta/2\qquad(W\in\{X,Z\}),
477		\]
478		then, writing $\Pi=\Id_R\ot\ket{E}\bra{E}$, one has
479		\[
480			\|\vartheta-\Pi\vartheta\|\leq2\sqrt\delta.
481		\]
482		In the projective setting of Lemma~\ref{lem:projective-strategy-setup},
483		take $R=AA'BB'$. For every vector $\vartheta$ on the six registers, set
484		$\mathrm{aux}_0=(\Id_R\ot\bra{E})\vartheta$. Then
485		$\mathrm{aux}_0\ot E=\Pi\vartheta$. If $\vartheta$ is a unit vector, there is
486		a unit vector $\mathrm{aux}$ on $R$ such that
487		\[
488			\|\vartheta-\mathrm{aux}\ot E\|
489			\leq2\|\vartheta-\Pi\vartheta\|.
490		\]
491	\end{theorem}
492	\begin{proof}
493		\leanok
494		\uses{lem:pauli-observable-expansion, def:generalized-pauli, def:EPR}
495		Fourier inversion shows that $H_Z$ keeps precisely the equal computational
496		labels. Averaging the simultaneous shifts gives $H_XH_Z=\ket{E}\bra{E}$.
497		Each $\Id_R\ot H_W$ is an average of unitaries, hence is a contraction.
498		Expanding the squared distance gives
499		$\|\vartheta-(\Id_R\ot H_W)\vartheta\|^2\leq\delta$.
500		The product identity and the triangle inequality now bound
501		$\|\vartheta-\Pi\vartheta\|$ by $2\sqrt\delta$.
502		The partial-inner-product formula gives
503		$\mathrm{aux}_0\ot E=\Pi\vartheta$. Normalizing $\mathrm{aux}_0$
504		at most doubles its distance from $\vartheta$, by the reverse triangle
505		inequality. If $\mathrm{aux}_0=0$, the projection error is one; the
506		original strategy state tensored with one EPR pair supplies a unit
507		reference vector on $R$, and the required distance is at most two.
508	\end{proof}
