546	\begin{lemma}[Pauli comparison after a change of state]
547	  \label{lem:qld-pauli-overlap-state-transfer}
548	  \lean{MIPStarRE.QPBT.pauli_overlap_transfer}
549	  \lean{MIPStarRE.QPBT.pauli_distance_on_ideal_le}
550	  \lean{MIPStarRE.QPBT.extraction_small_error_absorption}
551	  \leanok
552	  \uses{def:generalized-pauli, def:EPR, def:povm-distance}
553	  Let $A=\{A_h\}$ and $B=\{B_h\}$ be arbitrary local POVMs, and let
554	  $\vartheta$ and $\Phi$ be unit vectors on the associated bipartite space.
555	  Write
556	  \[
557	    E_{A,B}(\vartheta)=\mathbb E_u\sum_a
558	      \langle\vartheta,A_{[g_h(u)=a]}\ot B_{[g_h(u)=a]}\vartheta\rangle.
559	  \]
560	  Then
561	  \[
562	    E_{A,B}(\vartheta)
563	    \leq \sum_h\langle\Phi,A_h\ot B_h\Phi\rangle
564	      +md/q+2\|\vartheta-\Phi\|.
565	  \]
566	  In particular, let $A$ act on
567	  $\mathcal H_A\ot\mathbb C^{q^M}$, take $B$ to be the canonical Pauli
568	  projectors on $\mathcal H_B\ot\mathbb C^{q^M}$, and set
569	  $\Delta=\mathrm{aux}\ot\mathrm{EPR}_q^{\ot M}$ in local player order for a
570	  unit auxiliary vector. For either Pauli basis,
571	  \[
572	    \sum_h\|((A_h-\Id_{\mathcal H_A}\ot\tau^W_h)\ot\Id)\Delta\|^2
573	    \leq 2(1-E_{A,B}(\vartheta))+2md/q+4\|\vartheta-\Delta\|.
574	  \]
575	  These bounds are independent of the dimensions and the number of answers.
576	  Finally, for $0\leq\delta\leq1$ and $C\geq18$, both $16\delta$ and
577	  $2\delta+2md/q+16\sqrt\delta$ are at most $C(\delta^{1/4}+md/q)$.
578	\end{lemma}
579	\begin{proof}
580	  \leanok
581	  \uses{lem:sandwich-evaluated-diagonal-overlap,
582	    lem:schwartz-zippel-total-degree, fact:agreement,
583	    lem:pauli-observable-expansion}
584	  A selected sum of effects of the product POVM is a positive contraction.
585	  Its expectation changes by at most twice the distance between unit vectors.
586	  Schwartz--Zippel bounds the unequal-encoding contribution by $md/q$.
587	  Symmetry of the Pauli projectors moves their action across the EPR pair,
588	  and the agreement inequality bounds the full distance by twice the overlap
589	  deficit. The scalar bounds follow from $\delta,\sqrt\delta\leq\delta^{1/4}$.
590	\end{proof}
